CREATE FUNCTION public.reservar_directiva(p_nombre text,p_email text,p_socio uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'No autorizado'; END IF; IF length(trim(p_nombre))=0 OR p_email !~ '^[^ @]+@[^ @]+\.[^ @]+$' OR lower(p_email)=(SELECT lower(email) FROM public.profiles WHERE id=auth.uid()) THEN RAISE EXCEPTION 'Datos no válidos'; END IF; INSERT INTO public.equipo_invitaciones(nombre,email,socio_id) VALUES(trim(p_nombre),lower(trim(p_email)),p_socio) ON CONFLICT(email) DO UPDATE SET nombre=excluded.nombre,socio_id=excluded.socio_id,estado='Invitado' RETURNING id INTO n; RETURN n; END $$;
CREATE FUNCTION public.vincular_directiva(p_invitacion uuid,p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.equipo_invitaciones; BEGIN IF NOT public.is_super_admin() OR p_user=auth.uid() THEN RAISE EXCEPTION 'No autorizado'; END IF; SELECT * INTO i FROM public.equipo_invitaciones WHERE id=p_invitacion FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_user AND lower(email)=i.email) THEN RAISE EXCEPTION 'Cuenta no válida'; END IF; INSERT INTO public.profiles(id,email,nombre,socio_id) VALUES(p_user,i.email,i.nombre,i.socio_id) ON CONFLICT(id) DO UPDATE SET email=excluded.email,nombre=excluded.nombre,socio_id=coalesce(excluded.socio_id,profiles.socio_id); INSERT INTO public.user_roles(user_id,role) VALUES(p_user,'directiva') ON CONFLICT(user_id) DO UPDATE SET role=excluded.role; UPDATE public.equipo_invitaciones SET user_id=p_user WHERE id=i.id; END $$;
CREATE FUNCTION public.sync_club_email() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL THEN UPDATE public.profiles SET estado='Activo' WHERE id=NEW.id; UPDATE public.equipo_invitaciones SET estado='Activo' WHERE user_id=NEW.id; END IF; RETURN NEW; END $$; CREATE TRIGGER club_email_confirmed AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_club_email();
REVOKE ALL ON FUNCTION public.reservar_directiva(text,text,uuid),public.vincular_directiva(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reservar_directiva(text,text,uuid),public.vincular_directiva(uuid,uuid) TO authenticated;